def semver_sort(versions):
    def parse(v):
        main_build = v.split('+', 1)[0]
        if '-' in main_build:
            core, pre = main_build.split('-', 1)
        else:
            core, pre = main_build, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0  # has prerelease sorts before
            idents = pre.split('.')
            pre_key = []
            for ident in idents:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            pre_key = tuple(pre_key)

        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

